assert_first_line_prefix() {
    local label="$1"
    local file="$2"
    local prefix="$3"
    local first
    first=$(head -n 1 "$file")
    case "$first" in
        "$prefix"?*) ;;
        *) fail "$label should start with '$prefix'";;
    esac
}

assert_last_line_eq() {
    local label="$1"
    local file="$2"
    local expected="$3"
    local last
    last=$(tail -n 1 "$file")
    [ "$last" = "$expected" ] || fail "$label should end with '$expected'"
}

assert_contains_line() {
    local label="$1"
    local file="$2"
    local expected="$3"
    grep -Fxq "$expected" "$file" || {
        echo "FAIL: $label missing line: $expected" >&2
        echo "--- actual ---" >&2
        sed -n '1,120p' "$file" >&2
        exit 1
    }
}

assert_not_contains() {
    local label="$1"
    local file="$2"
    local unexpected="$3"
    ! grep -Fq "$unexpected" "$file" || fail "$label should not contain: $unexpected"
}

assert_available_has() {
    local label="$1"
    local expected="$2"
    local line
    line=$(tail -n 1 out)
    case "$line" in
        Available\ Backends:*\[*"$expected"*\]*) ;;
        *) fail "$label Available Backends should contain '$expected'; got '$line'";;
    esac
}

assert_available_lacks() {
    local label="$1"
    local unexpected="$2"
