+	if !want.Type().AssignableTo(f.Type()) {
+		t.Fatalf("%T.%s has type %s; want %s", target, name, f.Type(), want.Type())
+	}
+	f.Set(want)
+}
+
+func codespecExportedField(t *testing.T, target interface{}, name string) interface{} {
+	t.Helper()
+	v := reflect.ValueOf(target)
+	if v.Kind() == reflect.Ptr {
+		if v.IsNil() {
+			t.Fatalf("cannot inspect %s on nil %T", name, target)
+		}
+		v = v.Elem()
+	}
+	f := v.FieldByName(name)
+	if !f.IsValid() || !f.CanInterface() {
+		t.Fatalf("%T must expose a public field named %s", target, name)
+	}
+	return f.Interface()
+}
+
+func codespecEncodeBody(t *testing.T, body encoder) []byte {
+	t.Helper()
+	encoded, err := encode(body, nil)
+	if err != nil {
+		t.Fatalf("encode failed: %v", err)
+	}
+	return encoded
+}
+
+func TestCodespecMetadataRequestVersionsAndFlags(t *testing.T) {
+	legacyBody := []byte{0xff, 0xff, 0xff, 0xff, 0x01}
+	for _, version := range []int16{6, 7} {
+		req := &MetadataRequest{Version: version, AllowAutoTopicCreation: true}
+		got := codespecEncodeBody(t, req)
+		if !bytes.Equal(got, legacyBody) {
+			t.Errorf("metadata request v%d body = %v; want v5-compatible %v", version, got, legacyBody)
+		}
+		decoded := &MetadataRequest{}
+		if err := versionedDecode(got, decoded, version); err != nil {
+			t.Fatalf("decode metadata request v%d: %v", version, err)
+		}
+		if !reflect.DeepEqual(decoded, req) {
+			t.Errorf("metadata request v%d round trip = %#v; want %#v", version, decoded, req)
+		}
+	}
+
+	flagCases := []struct {
+		name         string
+		clusterFlag  bool
+		topicFlag    bool
+		trailingWire []byte
+	}{
+		{"cluster-only", true, false, []byte{0x01, 0x00}},
+		{"topic-only", false, true, []byte{0x00, 0x01}},
+	}
+	for _, tc := range flagCases {
+		t.Run(tc.name, func(t *testing.T) {
+			req := &MetadataRequest{Version: 8, Topics: []string{"orders"}}
+			codespecSetExportedField(t, req, "IncludeClusterAuthorizedOperations", tc.clusterFlag)
+			codespecSetExportedField(t, req, "IncludeTopicAuthorizedOperations", tc.topicFlag)
+			wantV8 := append([]byte{
+				0x00, 0x00, 0x00, 0x01,
+				0x00, 0x06, 'o', 'r', 'd', 'e', 'r', 's',
+				0x00,
+			}, tc.trailingWire...)
+			encoded := codespecEncodeBody(t, req)
+			if !bytes.Equal(encoded, wantV8) {
+				t.Fatalf("metadata request v8 body = %v; want %v", encoded, wantV8)
+			}
+
+			decoded := &MetadataRequest{}
+			if err := versionedDecode(encoded, decoded, 8); err != nil {
+				t.Fatalf("decode v8 request: %v", err)
+			}
+			if !reflect.DeepEqual(decoded.Topics, []string{"orders"}) || decoded.AllowAutoTopicCreation {
+				t.Fatalf("decoded v8 base fields = %#v", decoded)
+			}
+			if got := codespecExportedField(t, decoded, "IncludeClusterAuthorizedOperations"); got != tc.clusterFlag {
+				t.Errorf("decoded IncludeClusterAuthorizedOperations = %v; want %v", got, tc.clusterFlag)
+			}
+			if got := codespecExportedField(t, decoded, "IncludeTopicAuthorizedOperations"); got != tc.topicFlag {
+				t.Errorf("decoded IncludeTopicAuthorizedOperations = %v; want %v", got, tc.topicFlag)
+			}
+		})
+	}
+
+	if _, err := encode(&MetadataRequest{Version: 9}, nil); err == nil {
+		t.Error("metadata request v9 encoded successfully; versions above 8 must remain unsupported")
+	}
+}
+
+func TestCodespecMetadataRequestMinimumBrokerVersions(t *testing.T) {
+	cases := []struct {
+		name          string
+		request       int16
+		brokerVersion KafkaVersion
+	}{
+		{"v6-before-2.0", 6, V1_1_1_0},
+		{"v7-before-2.1", 7, V2_0_1_0},
+		{"v8-before-2.3", 8, V2_2_0_0},
+	}
+	for i, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			mock := NewMockBroker(t, int32(50+i))
+			defer mock.Close()
+			mock.SetHandlerByMap(map[string]MockResponse{
+				"MetadataRequest": NewMockMetadataResponse(t),
+			})
+			broker := NewBroker(mock.Addr())
+			config := NewConfig()
+			config.Version = tc.brokerVersion
+			if err := broker.Open(config); err != nil {
+				t.Fatalf("open broker: %v", err)
+			}
+			defer safeClose(t, broker)
+			if _, err := broker.GetMetadata(&MetadataRequest{Version: tc.request}); err != ErrUnsupportedVersion {
+				t.Errorf("metadata v%d against Kafka %s returned %v; want ErrUnsupportedVersion", tc.request, tc.name, err)
+			}
+		})
+	}
+}
+
+func TestCodespecMetadataResponseV6Compatibility(t *testing.T) {
+	wire := []byte{
+		0x00, 0x00, 0x00, 0x05,
+		0x00, 0x00, 0x00, 0x00,
+		0x00, 0x09, 'c', 'l', 'u', 's', 't', 'e', 'r', 'I', 'd',
+		0x00, 0x00, 0x00, 0x02,
+		0x00, 0x00, 0x00, 0x00,
+	}
+	response := &MetadataResponse{}
+	if err := versionedDecode(wire, response, 6); err != nil {
+		t.Fatalf("decode v6 response: %v", err)
+	}
+	if response.Version != 6 || response.ThrottleTimeMs != 5 || response.ControllerID != 2 || response.ClusterID == nil || *response.ClusterID != "clusterId" {
+		t.Fatalf("decoded v6 response = %#v", response)
+	}
+	if got := codespecEncodeBody(t, response); !bytes.Equal(got, wire) {
+		t.Errorf("re-encoded v6 response = %v; want %v", got, wire)
+	}
+}
+
+func TestCodespecMetadataResponseV7LeaderEpoch(t *testing.T) {
